//! Codegen parity rows for the codegen-only corpus clusters (bot/template C). Each row is
//! (source, enableStaticContentOptimization, expected) where `expected` was recorded from
//! @lwc/template-compiler compile() at the pinned oracle b9e8007 (file `x.html`), whitespace-stripped
//! like the corpus compare, from after the `lwc` import to the end.

fn body(src: &str, static_opt: bool) -> String {
    body_with(src, lwc_template::Config { enable_static_content_optimization: Some(static_opt), ..Default::default() })
}

fn body_with(src: &str, cfg: lwc_template::Config) -> String {
    let mut code: String = lwc_template::compile(src, "x.html", cfg).unwrap().code.split_whitespace().collect();
    // Like oracle.cjs: drop the `/*LWC compiler vX*/` banner (byte-exact placement is `banner_like_astring`).
    if let Some(a) = code.find("/*LWCcompilerv") { let b = a + code[a..].find("*/").unwrap() + 2; code.replace_range(a..b, ""); }
    let from = code.find("from\"lwc\";").map_or(0, |i| i + 10);
    code[from..].to_string()
}

fn check(rows: &[(&str, bool, &str)]) {
    for (src, static_opt, want) in rows {
        assert_eq!(body(src, *static_opt), *want, "{src}");
    }
}

